head.script:
requires("uiplugin.popup");

scwin.onpageload = function() {
	var option = {
		title : "edu001"
		, src : "WindowContainer_browserPopup_WESE-598_(WSQ-5479)_sub1.xml"
		, windowTitle : "TEST"
		, windowId : "edu001"
		, openAction : "selectWindow"
		, frameMode : "wframe"   /// <--- 명시하면 오류 발생
	}
	window1.createWindow(option);
};

	scwin.checkVal = function() {
		var checkError = WebSquare.logger.getLog();
		return checkError.indexOf('Cannot read properties of undefined') == -1;
	}		

	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('window1_subWindow0_wframe_btn_trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('window1_closeAll').click()");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "400");

		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
